#!/usr/bin/env node
/* Small rolling fixture snapshot for the homepage.
 * Regenerated by the daily-results workflow; authoritative calendar stays unchanged. */
'use strict';
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'..');
const src=JSON.parse(fs.readFileSync(path.join(root,'data/match-calendar.json'),'utf8'));
if(!Array.isArray(src.matches)||src.matches.length<2000)throw Error('Calendar unexpectedly incomplete');
const kstDate=new Date(Date.now()+9*3600000).toISOString().slice(0,10);
function shift(iso,days){return new Date(Date.parse(iso+'T12:00:00Z')+days*86400000).toISOString().slice(0,10)}
const windowStart=shift(kstDate,-4),windowEnd=shift(kstDate,28);
const matches=src.matches.filter(m=>m.date>=windowStart&&m.date<=windowEnd);
const snapshot={
 season:src.season,capturedAtKst:src.capturedAtKst,verifiedAtKst:src.verifiedAtKst||null,
 provider:src.provider,providerUrl:src.providerUrl,sourceByLeague:src.sourceByLeague,
 windowStart,windowEnd,generatedAtKst:kstDate,
 matches
};
if(!matches.length)throw Error('No fixtures in rolling window; refusing to replace data');
fs.writeFileSync(path.join(root,'data/nearby-fixtures.json'),JSON.stringify(snapshot)+'\n');
console.log('Homepage fixtures:',windowStart,'to',windowEnd,'·',matches.length,'matches');
